#include <stdio.h>

char arr[40];
int len;

void print_para(char A[], char a) {
    static int i = 0;
    static int j = 0;
    if (i != 0) A[i+j-1] = a;
    if (i < len) {
        if (j < i) {
            j++;
            print_para(A, '}');
            j--;
            i++;
            print_para(A, '{');
            i--;
        }
        else {
            i++;
            print_para(A, '{');
            i--;
        }
    }
    else {
        int x = 0;
        for (x = 0; x < (2*len); x++) {
            printf("%c", A[x]);
        }
        if (j != len) {
            for (x = i+j; x < (2*len); x++) {
                printf("}");
            }   
        }
        printf(" \n");
    }
}

int main() {
    scanf("%d", &len);
    print_para(arr, '{');
    return 0;
}

